; Huffman-compressed text group(s): $28
; Text $0500: You came to see the King?
; Text $0501: If so,proceed through this door.
; Text $0502: Then you came for the tournament,correct? Proceed through one of the two small doors on either side.
; Text $0503: Have you been to the north already?
; Text $0504: You reached a wrecked bridge? Who did such a terrible thing?
; Text $0505: Even if you want to go,you can't,right?
; Text $0506: How are you doing? Winning?
; Text $0507: Good.Let it ride.Got it? Let it ride!
; Text $0508: Luck may come soon.Wait it out,OK?
; Text $0509: I'm so tired! Hey brother,how's it going? Are you making money?
; Text $050A: That's good.
; Text $050B: Well,keep trying!
; Text $050C: Welcome! How would you like a map of the world?
; Text $050D: Funny,I thought I had some more.They're gone.Hmm....
; Text $050E: Are you sure? Well,come back any time.
; Text $050F: This is a village that even time has left behind.'<4F>Are you familiar with the legend of the Sandglass of Regression?
; Text $0510: I see....
; Text $0511: The legend says the Sandglass of Regression can reverse time slightly.
; Text $0512: Are you the one who wants to know about the Sandglass of Regression?
; Text $0513: Our ancestors used it in battle.'<4F>You use it to reverse time after a wrong move in battle.'<4F>It's not essential you own it,but it may come in handy.
; Text $0514: Very well.Feel free to stay.
; Text $0515: The world won't come to an end.'<4F>Tell me I'm right,please!
; Text $0516: You're so considerate...Sob...Sob...
; Text $0517: Sob...Sob...
; Text $0518: Aha! You monsters! Oops...I was just dreaming....
; Text $0519: Worry for my missing child makes sleep impossible....Please find my child....
; Text $051A: The King is asleep.
; Text $051B: Stay at an inn tonight and come back tomorrow.
; Text $051C: Hmm...the more I compare,the more similarity I find.'<4F>The present weather resembles that of past times when monsters reigned.
; Text $051D: Ho hum...guarding isn't fun.
; Text $051E: I'll go to sleep.I'm happiest when I go to sleep.
; Text $051F: We're closed for today.Come back tomorrow.
