; Huffman-compressed text group(s): $29
; Text $0520: Hmm...something awful may be happening somewhere.
; Text $0521: Monsters seem to be getting stronger.
; Text $0522: The woman of this house is waiting for her missing husband to return.How sad....
; Text $0523: Weep...I want to go to the bathroom,but I'm too scared!
; Text $0524: How long will she wait? She should give up hope and marry me.
; Text $0525: We were just talking about the incidents.'<4F>I believe the children know something.
; Text $0526: Don't worry,Principal.'<4F>Children always have secrets.
; Text $0527: Can kids really vanish before your eyes? It's impossible!
; Text $0528: They say the man in the underground jail is named Alex.He's my pal.
; Text $0529: My wife says Pocos was playing with some funny shoes when he vanished....
; Text $052A: What? I'm not snooping!'<4F>Keep quiet,and I'll tell you something.'<4F>I saw the man in the underground jail before...in the Castle Town of Burland...maybe.'<4F>Why don't you go back there?
; Text $052B: I'm a traveler.I'm going to take a bath.Please leave.
; Text $052C: Alex,let's play again tomorrow.Mumble...Mumble...
; Text $052D: Our son vanished too!'<4F>Who's doing this? What do they want?
; Text $052E: Yes,I'm Alex...monsters are coming! I'm scared!
; Text $052F: Sss...Sss...
; Text $0530: I feel anxious.I can't sleep.
; Text $0531: Yum...Yum...I'm hungry.
; Text $0532: Gurg...Gurg...Princess...oh,no...Mumble...Mumble...
; Text $0533: We were just speaking of the Princess.
; Text $0534: The Princess is leaving on a journey? Of course,I won't tell anyone.'<4F>I'm known to be tight-lipped.Heh,Heh,Heh!
; Text $0535: Now I can take care of my business.Thanks.
; Text $0536: Thanks for everything.
; Text $0537: Thanks.Have a safe journey.
; Text $0538: I think I've seen you before....'<4F>Was it at the Castle? I can't remember.
; Text $0539: You don't look like commoners.'<4F>Aren't you of noble birth?
; Text $053A: I was right.You're the Princess' Party!
; Text $053B: OK...if you say so.
; Text $053C: Whew! I'm tired.Come back tomorrow.
; Text $053D: Grzz...Grzz...
; Text $053E: We travel from place to place giving bazaars like this.
; Text $053F: On nights like this,when I can see the stars clearly,I get homesick.
Bank02_TextGroup_29:
