; Huffman-compressed text group(s): $2A
; Text $0540: Grzz...Grzz...
; Text $0541: I'm Ragnar,a soldier from Burland.I'm searching for the Hero.'<4F>...guess you wouldn't understand what I'm talking about....Excuse me.
; Text $0542: Look! A shooting star!'<4F>I hope it's not a bad omen.
; Text $0543: I'm grateful I had another peaceful day.
; Text $0544: Meals after hard work taste great.
; Text $0545: I'm not full yet.
; Text $0546: This is the Castle Town of Endor.
; Text $0547: Sss...Sss...
; Text $0548: You want to buy the shop? No,you'd better not.You don't have business experience.
; Text $0549: The tournament is only held during the day.Come back again.
; Text $054A: Grzz...Grzz...
; Text $054B: How many soldiers have been done in by Necrosaro!'<4F>It's like an extermination.
; Text $054C: The King and the Princess are both asleep.
; Text $054D: I have to clean here.Clean...Clean...
; Text $054E: I bet Necrosaro will be the winner.He looks mean!
; Text $054F: I just don't like that man called Necrosaro.
; Text $0550: I can't keep up with women's silly talk.
; Text $0551: Umm...Umm...Zzz...Zzz...
; Text $0552: Sss...Sss...
; Text $0553: Zzz...Zzz...
; Text $0554: Welcome home,daddy! Yes,I've been a good boy.'<4F>When I grow up,I'll work as hard as you and let you two live in comfort!
; Text $0555: Let's hope the world won't end.'<4F>Without the world,you won't have any business.
; Text $0556: You may not enter the Castle at night!
; Text $0557: It's late.Come back tomorrow.
; Text $0558: Prince! Prince! Oh no! Where is he?
; Text $0559: They say the monsters began appearing because the Ruler of Evil is about to revive.
; Text $055A: You must have the King's permission to own a shop in this town.'<4F>It's not easy to get his permission.
; Text $055B: I was sure that Necrosaro would win the tournament....
; Text $055C: I think Necrosaro disappeared from the tournament because he had more important things to do.
; Text $055D: I hear the Hero,who will save this world,is growing up somewhere.
; Text $055E: There's a rumor that the Ruler of Evil will revive....'<4F>I just don't know what to believe....
; Text $055F: Greetings! Eat and sing! Forget your problems!
