; Huffman-compressed text group(s): $2B
; Text $0560: Hey! Aren't you Edgar's daughters?'<4F>Did he succeed in turning iron into gold?'<4F>If he did,he could become a king.
; Text $0561: I wonder why Edgar was murdered by his pupil,Balzack....
; Text $0562: Alchemy? Yes,I know.Isn't it a method of turning iron into gold?
; Text $0563: Good food after work is the best! Ah,so delicious!
; Text $0564: Zzz...I strive to save the injured...Zzz...
; Text $0565: Let's dance and enjoy the music!
; Text $0566: Many girls are summoned to the feasts held almost every night at Keeleon Castle.'<4F>No girl ever returns from there!
; Text $0567: Curses! Where did Lynn go?'<4F>She's been summoned to Keeleon Castle.
; Text $0568: He came back and fell asleep while I was out looking for him.Where was he?
; Text $0569: Zzz...Zzz...that cave has a secret...Zzz...Zzz...
; Text $056A: I hope you find Balzack,the object of your revenge,soon.
; Text $056B: People like you shouldn't come here.
; Text $056C: What? Is this a Pufpuf room? I can't tell you.
; Text $056D: This was Lynn's room.Where is she now?
; Text $056E: <4E>Master:'The Castle people are summoning girls to the Castle.They say they are having feasts there.'<44>Master:'Where's the Castle? It's far north from here beyond Kievs.'
; Text $056F: I'm a new dancer.'<4F>I'll try to become as popular as Mara,the former star here.
; Text $0570: Wow! I love watching the show up close!
; Text $0571: This crowd! Don't they have anything better to do?
; Text $0572: I bought the cheapest ticket...I didn't know I'd be stuck in the back!
; Text $0573: Yeee Haaaa!
; Text $0574: The man behind me is noisy.'<4F>Can't he act like a gentleman?
; Text $0575: I can't see a thing! The post blocks my view!
; Text $0576: Watching dance relaxes me....
; Text $0577: The new King of Keeleon's taxation is severe.'<4F>I have to work late every day.Grumble...Grumble...
; Text $0578: Uuur...Uuur...
; Text $0579: I heard an awful rumor on my way here.'<4F>The new King of Keeleon has allied himself with the evil ones.
; Text $057A: The old man next to me talks in his sleep.I can't sleep.
; Text $057B: Zzz...Zzz...Ah...Ah-choo!...Zzz...Zzz...
; Text $057C: My grandpa is here again.'<4F>Endor must be dear to him,but we can't see Endor from here....
; Text $057D: Zzz...Zzz...
; Text $057E: Zzz...Zzz...
; Text $057F: Our father used to work in this country's mine.'<4F>We came here to see him,but he died before our arrival.'<4F>What should I tell my little brother,Pipin? Sob...
Bank02_TextGroup_2B:
