; Huffman-compressed text group(s): $2C
; Text $0580: Zzz...Zzz....Father,it's me,Pipin! Mumble...Mumble...
; Text $0581: Welcome! Eat and sing! Have a good time!
; Text $0582: I'm Joy.Let's dance!
; Text $0583: It's hard to keep up with all the orders.
; Text $0584: Where's my order? Where is it?
; Text $0585: I hear a princess won the tournament in Endor.
; Text $0586: This is the grave of my wife,Helga.'<4F>Dear Helga,the time of our reunion seems to be nearing....
; Text $0587: I don't feel good.I need a rest.Come back tomorrow.Cough...Cough...
; Text $0588: My grandpa is an expert in gunpowder manufacturing,but it's prohibited now.
; Text $0589: Zzz...Zzz...
; Text $058A: Cough...Cough...
; Text $058B: Cough...Cough...That mine should yield more gold.'<4F>I won't give up...Cough...Cough...
; Text $058C: A curse on those who raid our ruins....Crackle...Crackle...
; Text $058D: The King is asleep.
; Text $058E: Doze...'
; Text $058F: An old man stands by the pond every night.'<4F>It's creepy!
; Text $0590: Oh,that old man started rambling nonsense again.
; Text $0591: The wedding is only held during the day.
; Text $0592: It's our custom to continue weddings for several days.'<4F>Come back tomorrow.
; Text $0593: Necrosaro was a monster...he disappeared in the middle of...
; Text $0594: Ho,Ho,Ho! I never expected the Princess to marry so young.'<4F>Now I've lost my place to sleep.Ho,Ho,Ho!
; Text $0595: Mia...I love you...Zzz...Zzz...
; Text $0596: Sss...Sss...Father,I'm sorry...Sss...Sss
; Text $0597: Cleaning up is hard work.Don't bother me.
; Text $0598: A merchant named Taloon stopped by this town.'<4F>He had lots of money and was talking about buying a ship.What an ambitious man!
; Text $0599: Waaa...I'm scared...Monsters are here...Zzz...Zzz...
; Text $059A: That spa must have been really good for him.He's sleeping like a baby.
; Text $059B: This wharf is closed at night.
; Text $059C: My ship...Zzz...Zzz...
; Text $059D: Are you searching for someone? I saw an unusual group of three people.'<4F>It was a princess and her escorts.They said they were after a man called Necrosaro.
; Text $059E: Taloon is a fine example of an arms merchant!'<4F>He plans to travel the world in his own ship to search for legendary weapons.
; Text $059F: Sure...a sea voyage is nice....
