; Huffman-compressed text group(s): $2D
; Text $05A0: I wish I could save enough money to buy my own ship too...'<4F>but I spend too much! Why?
; Text $05A1: If you have love,an age difference doesn't matter.Is there really such a proverb?
; Text $05A2: My husband! He thinks too much.'<4F>That's why he's growing bald!
; Text $05A3: Starboard the Helm! Just joking!
; Text $05A4: Mumble...Mumble...The ship is sailing out...Grzz...Grzz...
; Text $05A5: Huh? I fell asleep.That old man's stories are boring.
; Text $05A6: Ah,<4B>Ah,<4B>Ah...'<4F>Ah-choo! It gets chilly at night.
; Text $05A7: <4E>Howden:'I opened an inn,hoping to meet travelers who had information that would help me uncover the secret of the Treasure Map.'<44>Howden:'I've made enough money already.I don't need any more treasure.'
; Text $05A8: Old Howden's success began when he opened an inn here.
; Text $05A9: My hometown is in the far reaches of this land.It's a village with a small castle.'<4F>I wonder if they still grow Padequia.
; Text $05AA: I remember that a short time ago,a rugged man named Ragnar was in this town.
; Text $05AB: This is Soretta Castle.The King is already asleep.
; Text $05AC: Zzz...Zzz...I'm happy just to have a roof over my head.
; Text $05AD: I'm in love.Blush...
; Text $05AE: Taloon!'<4F>It's me,Tom's son.Your wife sold me this house.'<4F>I'm determined to become a great merchant like you.
; Text $05AF: The tide always rises like this at night and submerges the beach.
; Text $05B0: Is there really a castle above the clouds?
; Text $05B1: Grzz...Grzz...
; Text $05B2: His appetite is amazing!
; Text $05B3: Working on my boat shop makes me hungry.Where's my meal?
; Text $05B4: Where did the shaman go?
; Text $05B5: Umm...I can't come up with a good joke.'<4F>Why does the King want a hearty laugh in these troubled times anyway?
; Text $05B6: Customers are gloomy these days.
; Text $05B7: No matter what,we'll all be destroyed by someone called the Ruler of Evil.'<4F>What good will my work do anyway?
; Text $05B8: I hope the time when we can all laugh heartily will come soon.
; Text $05B9: Zzz...Zzz...Laugh and grow fat...Mumble...Mumble...
; Text $05BA: Why did the deer cross the road? Because the chicken was on vacation! Not bad,right?
; Text $05BB: The King is already asleep.
; Text $05BC: Which cave should we explore next?'<4F>I'll talk with Pocos.
; Text $05BD: We close the gate at night for safety.'<4F>Come back tomorrow.
; Text $05BE: Zzz...Zzz.Cry harder! Shed ruby teardrops! Mumble...Mumble...
; Text $05BF: A young monster called Saro used to live in this village.'<4F>He left the village determined to rule the world.'<4F>He was gentle to Rosa,though.
