; Huffman-compressed text group(s): $2E
; Text $05C0: Can we really make flying vessels?
; Text $05C1: According to old books,the essential component of the flying vessels was kept in a sturdy canister.
; Text $05C2: I'm too tired from work.'<4F>I don't want to hear her silly talk about a giant statue that walks.
; Text $05C3: I hear the Golden Bracelet,which was for sale,was stolen by monsters.'<4F>What will they do with such a thing?
; Text $05C4: Crackle...Crackle....You may go if you want to....'<4F>But I'm sure your ship will be sent to the bottom of the sea....
; Text $05C5: Oh,no! The ship is sinking! Mumble...Mumble...
; Text $05C6: The sky looks ominous!'<4F>I'm afraid the Ruler of Evil is about to resurrect!
; Text $05C7: <4E>No answer.<43>Seems to be a corpse.
; Text $05C8: Meow...'
; Text $05C9: Zzz...Zzz...
; Text $05CA: Sss...Sss...
; Text $05CB: Doze...Doze...
; Text $05CC: Grzz...Grzz...
; Text $05CD: Sss...Sss...
; Text $05CE: Umm...Umm...
; Text $05CF: Gurg...Gurg...
; Text $05D0: Sss...Sss...
; Text $05D1: You can record your progress at any House of Healing.'<4F>Wherever you go,find one...'<4F>and record your progress on the Imperial Scrolls of Honor.
; Text $05D2: Our King is truly admirable.
; Text $05D3: This is the King of Burland's chamber.
; Text $05D4: The sky makes me uneasy these days.
; Text $05D5: Don't fall behind the other soldiers.
; Text $05D6: Hey,Ragnar,still here?'<4F>Haven't the others already left for Izmit Village?
; Text $05D7: I hear that monsters which only appeared at night are now appearing during the day.Troubled times,aren't they?
; Text $05D8: We came from Izmit Village.
; Text $05D9: If you get injured,return to a town and rest at an inn.
; Text $05DA: For long trips,take along Medical Herbs.
; Text $05DB: This is Burland Castle.
; Text $05DC: I won't let anyone suspicious pass!
; Text $05DD: Monsters have been around for some time.They may be the cause of the recent disappearances of children.
; Text $05DE: If you keep walking outside,night will fall.
; Text $05DF: Oh,Ragnar,I'm researching something.
Bank02_TextGroup_2E:
