; Huffman-compressed text group(s): $2F
; Text $05E0: This is the Castle Town of Burland.
; Text $05E1: Burland's King is good-natured and keeps taxes low.'<4F>Unfortunately he can't spend much on your equipment.'<4F>Accumulate gold to buy more powerful weapons and armor.'<4F>Be sure to equip yourself with them after you buy them.
; Text $05E2: Izmit Village is on the coast beyond the cave west of this Castle.
; Text $05E3: Even though they're strong,monsters can't enter towns.
; Text $05E4: <4E><44>'But why do children vanish?'
; Text $05E5: You may find out something at Izmit Village.
; Text $05E6: Is it true that children are vanishing?'<4F>I'm not a kid anymore,so I guess I'm safe.
; Text $05E7: Welcome to Izmit Village.
; Text $05E8: I'm a traveling prophetess.I can see the future.'<4F>A chosen one will soon appear somewhere in this world.
; Text $05E9: The man in jail stole some bread.Seems he lost his memory....'<4F>He acts like a child.He must have been through some ordeal.
; Text $05EA: Soldier,please find my child!'<4F>He vanished like smoke before my eyes.
; Text $05EB: This is a school.
; Text $05EC: Hey,Ragnar,it's you.You came to this village too.'<4F>The tower west of here looks suspicious.I wonder how we can get in.
; Text $05ED: Wait! Stop!
; Text $05EE: No way!
; Text $05EF: You're a soldier.That's great!'<4F>I'll be a royal soldier someday.
; Text $05F0: Don't interrupt.I'm studying!
; Text $05F1: The missing child? Pocos of the inn?'<4F>He flew away into the sky.
; Text $05F2: Welcome,Soldier.I'm teaching now.'<4F>Perhaps we can talk at night.
; Text $05F3: Get me out,sir.I was hungry and took some bread.That's all I did.Sob...
; Text $05F4: Help me,sir! They say I'm the Hero and treat me badly!
; Text $05F5: I have no business with a lowly royal soldier!
; Text $05F6: Mother,he saved me.
; Text $05F7: How can I ever thank you?
; Text $05F8: Hurray! Hurray!
; Text $05F9: Thank you so much.'<4F>Remember me? I'm the mother who begged you to save my child at Burland Castle.
; Text $05FA: Hey,Ragnar! I'm impressed.
; Text $05FB: Now,I can teach without worry.Thank you.
; Text $05FC: I decided.I'll be a soldier too.
; Text $05FD: It's not true that the Ruler of Evil will resurrect,is it?
; Text $05FE: You're so strong!
; Text $05FF: You're a true soldier.Keep it up!
Bank02_TextGroup_2F:
