; Huffman-compressed text group(s): $30
; Text $0600: What? Our child has returned? Th...Thank you.
; Text $0601: Oh! You've found the vanished children! Th...Thank you.
; Text $0602: The man in jail went home with his wife.They told me to thank you for them.
; Text $0603: If I were young,we could have fought together....What a pity.
; Text $0604: Thank you.Now we can live without fear.
; Text $0605: We can let our kids outside now,can't we? Thank you.
; Text $0606: Yeah! Yeah! I can play outside tomorrow.
; Text $0607: I'm indebted to you for my husband's safe return.Thank you.
; Text $0608: You're that soldier! It's me,Alex.Thanks for saving me.
; Text $0609: Hurry! The King is waiting!
; Text $060A: I am counting on your good work,Ragnar.
; Text $060B: What are you waiting for? Go.Go now.
; Text $060C: Let's go slow,Ragnar.Let's go slow....
; Text $060D: <4E>Cristo:'Princess Alena,your tutor,Brey,told me you plan to go out alone.'<44>Cristo:'That's so reckless!'<44>Cristo:'If something happens to you,I...I mean the King will be devastated.'
; Text $060E: Something ominous is approaching from the eastern sky.'<4F>I hope nothing terrible will happen to our Castle.
; Text $060F: I must cook meals.I'm so busy.
; Text $0610: I hear the Princess is a real tomboy.'<4F>I'd like to see her in person.Heh,Heh...
; Text $0611: He's a nice man,but he has a big mouth.
; Text $0612: I'm so hungry.When will the food be ready?
; Text $0613: If the Princess leaves the Castle,she may fall into evil hands.
; Text $0614: Hurray! You came to beat the monster,right?
; Text $0615: This is Tempe,a cursed village.'<4F>If my daughter hadn't been born here,she'd still be alive.
; Text $0616: Some time ago a monster moved into the northern wood.'<4F>He threatens to destroy the village if we don't offer him young girls.
; Text $0617: I can't leave my parents....
; Text $0618: How tragic...that couples must be separated.
; Text $0619: Uhh,Nina,uhh....
; Text $061A: I'll never forget what you've done!
; Text $061B: You're so strong! Hmm...you're traveling to prove your strength.'<4F>I suggest you enter the tournament at Endor in the east.'<4F>You can go to Endor from the shrine southwest of here.
; Text $061C: Hurray! The monster's gone!
; Text $061D: We're getting married.
; Text $061E: I'd given up hope....Thank you so much.
; Text $061F: The item shop has opened again.Tempe will come back to life.'<4F>Thank you.
