; Huffman-compressed text group(s): $31
; Text $0620: If you go east after leaving the woods,you will reach Frenor.
; Text $0621: The innkeeper entertained the Princess' Party lavishly.'<4F>I might offer her my small savings too.
; Text $0622: The Golden Bracelet was our treasure.'<4F>It caused too much conflict among us and was finally hidden away in the southern cave.
; Text $0623: Oh,no! Princess!
; Text $0624: Gasp! I'm hurt.
; Text $0625: Bow,Wow!
; Text $0626: I can't believe it! May...I mean the Princess was kidnapped.
; Text $0627: Would you rescue the Princess? If you succeed,you'll be handsomely rewarded.
; Text $0628: This is the Town of Frenor.
; Text $0629: Neigh!'
; Text $062A: Rumor is there's a shrine,far east of here,which leads to Endor.
; Text $062B: Would you like these rare jars? Take a look.
; Text $062C: Try our delicious meals.You'll love them,I guarantee!
; Text $062D: I bought too many things.They're so heavy.
; Text $062E: They say a tournament is going on in Endor.
; Text $062F: If you go to Endor,watch the tournament.
; Text $0630: The door is locked.I can't go upstairs.
; Text $0631: The King told me.You can pass.
; Text $0632: Be careful on your journey.
; Text $0633: There should be a Travel Door to Santeem around here,but I can't find it.
; Text $0634: Welcome to the Castle Town of Endor.
; Text $0635: Do you know? A tournament will be held in the Castle.
; Text $0636: My worthless husband! Where is he?
; Text $0637: Hello! Please enjoy our meals.
; Text $0638: I lost again.What should I tell my wife?
; Text $0639: Many people are in Endor to see the tournament.
; Text $063A: Look! The clouds are moving swiftly to the west.What's happening?
; Text $063B: Are you asking if the shop downstairs is closed?'<4F>I'm old and plan to retire after selling it....'<44>
; Text $063C: Is there someone who wants to start a business here?
; Text $063D: Welcome to the Casino.'<4F>Only coins can be used here.Please purchase coins from the Coin Seller in the back.
; Text $063E: Alright! Via a Double-or-Nothing,I now have 16 coins instead of 8! I'm hooked!
; Text $063F: I'm out of luck today.
