; Huffman-compressed text group(s): $32
; Text $0640: You can exchange your coins with items at the Exchange Counter to the right.
; Text $0641: No matter how much you win,you won't be able to cash in coins.'<4F>It's wise to gamble only with the money you won't need.
; Text $0642: No! My day's wages are gone! Weep...
; Text $0643: If you go straight down this corridor,you'll come to a big building.It's the Coliseum.
; Text $0644: This is the Coliseum where the tournament is held.
; Text $0645: The King is upstairs.
; Text $0646: Monsters began appearing in Endor recently.'<4F>Our King started the tournament to attract the strong....
; Text $0647: If you enter the tournament,watch out for the man called Necrosaro.'<4F>He is immensely strong and utterly merciless.
; Text $0648: The tournament's winner will marry our Princess.'<4F>I sympathize with her.
; Text $0649: The King here is rash and does whatever comes to his mind.He worries everyone.
; Text $064A: This is the King of Endor's chamber.
; Text $064B: Necrosaro....What an unlucky name.
; Text $064C: I have to wipe the table clean.Wipe...Wipe...
; Text $064D: We have many things to wash.How busy!
; Text $064E: I'm afraid that the Princess will end up marrying the man called Necrosaro.
; Text $064F: Watch out for Necrosaro!
; Text $0650: To enter the tournament,take the left stairs.To just watch it,use the ones on the right.
; Text $0651: The fighting arena is upstairs.Once you're up there,there's no retreat.
; Text $0652: This is a shortcut to the outside of the Castle.Use it if you're in a hurry.
; Text $0653: Shut up! Don't talk to me!'<4F>I'm terribly sorry...I'm jittery before my fight.
; Text $0654: Hmm...terrifying...Necrosaro's strength is beyond our comprehension.
; Text $0655: I'm sure Necrosaro will be the winner.
; Text $0656: I just love this excitement!
; Text $0657: Excuse me! You're blocking my view!
; Text $0658: I wouldn't fight like that! No,not that way! Go,yeah,go like this!
; Text $0659: I'm watching this.Don't talk to me now.
; Text $065A: The man behind me is so noisy....
; Text $065B: Do you know? The winner of the tournament is a young woman.
; Text $065C: It seems the tournament is over.
; Text $065D: Really? You're Princess Alena? Congratulations! Have anything you want.It's on me!
; Text $065E: Maybe I ought to get an autograph!
; Text $065F: After Necrosaro vanished,monsters stopped appearing.
