; Huffman-compressed text group(s): $33
; Text $0660: Isn't there someone who wants to start a business here?
; Text $0661: Mumble...Mumble...see you later,daddy....
; Text $0662: The innkeeper said he wanted to talk to you.
; Text $0663: Bow,Wow.
; Text $0664: Do you want to talk to my husband? He's working now.Come back at night.
; Text $0665: What is this cave? I can't get a treasure chest!
; Text $0666: A short while ago water suddenly poured down from above.I almost drowned!'<4F>But I survived that ordeal and got to the treasure chests.Sorry!
; Text $0667: You came to find the Iron Safe too?'<4F>I think that rolling boulder has something to do with it.
; Text $0668: I hear that foxes who like to trick people live around here.Watch out for them.
; Text $0669: Hi,Traveler! Want to dance with me?
; Text $066A: I'm da Gardi,an architect.This girl won't let me go....'<4F>I decided to marry her and stay in this village.Ha,Ha,Ha.
; Text $066B: Why don't you stay in this village too?'<4F>Yelp,Yelp!'<4F>Oops,I caught a cold?
; Text $066C: Welcome to Bonmalmo Castle.
; Text $066D: I hear there are foxes around here who trick people.'<4F>A dog could get rid of them.
; Text $066E: So you came from Lakanaba,eh? A man from Lakanaba is imprisoned in the Castle.'<4F>To speak to him,you must evade the guards.
; Text $066F: We can't get to Endor because the bridge is broken.'<4F>Da Gardi,an architect,should be able to repair it easily....
; Text $0670: Where's da Gardi? Isn't he back yet?'<4F>We can't invade Endor until he repairs the bridge!
; Text $0671: Yelp,Yelp!
; Text $0672: I heard the prisoner from Lakanaba escaped.'<4F>Oh well,he was such a small time criminal,nobody cares.
; Text $0673: An architect named da Gardi just arrived.'<4F>I'm sure he'll fix the bridge soon!
; Text $0674: How skilled da Gardi is! He came here and repaired the bridge in no time.'<4F>Now I can invade Endor.Ha,Ha,Ha!
; Text $0675: Look how swiftly the clouds rush across the sky!'<4F>Something dreadful may be happening somewhere....
; Text $0676: So you came here to make money.'<4F>There are many ways to make money here,I guess.
; Text $0677: Did you know that a tournament was held at the Castle recently?
; Text $0678: The monsters disappeared shortly after the tournament,but they came back again.'<4F>What's going on?
; Text $0679: Look how swiftly the clouds rush across the sky!'<4F>Something dreadful may be happening somewhere....
; Text $067A: What a shop! How long must I wait?
; Text $067B: Alright,Daddy! You finally own a shop!
; Text $067C: A man named Necrosaro was about to win the tournament.'<4F>But he suddenly disappeared.I wonder why.
; Text $067D: Our King meets with all types of people.Watch your manners in front of him.
; Text $067E: Once,long ago,there was a sword called the Zenithian Sword.'<4F>Whoever possessed it was able to ascend into the sky.
; Text $067F: I hear that a man named da Gardi repaired many bridges.
