; Huffman-compressed text group(s): $34
; Text $0680: Are you the grocer? What? You're an arms merchant? Don't you know this is a kitchen?
; Text $0681: I'm Ragnar,a soldier of Burland.'<4F>I came here hoping that the person I've been looking for might be at the tournament....'<4F>But it's over and the Casino also seems to be closed for a while.
; Text $0682: Heave ho,Heave ho,Dig and Dig...'<4F>They say the Casino in Endor reopened.I'll go there soon!
; Text $0683: Dig and Dig and Dig and Dig...
; Text $0684: This is the country of Santeem.No outsiders can enter.You better go back.
; Text $0685: It's said that somewhere in this world,there's a sword called the Zenithian Sword.'<4F>Find it and give it to someone with a noble heart to save this world!
; Text $0686: We're going to Endor.
; Text $0687: Endor has a casino and an eatery.We can find jobs there!
; Text $0688: Sorry,the eatery opens at night.
; Text $0689: Though it was only for a short time,I enjoyed working with you.I hope you succeed in your pursuit of revenge.
; Text $068A: This is a theater.The Master is in the basement waiting room.
; Text $068B: I don't know who you're looking for.There's no one here but me.Get out!
; Text $068C: I hear Edgar,an alchemist in Kievs,was murdered by his pupil,Balzack.'<4F>What? You're his daughters? Oh,I feel so sorry for you.
; Text $068D: This is Monbaraba,a town of music and dance.The Village of Kievs is in the north.
; Text $068E: I hear Lynn from the eatery ran away.She was so popular.
; Text $068F: That Lynn! Where did she go? I'll punish her if I find her!
; Text $0690: Oh,so you're searching for the man who murdered your father.
; Text $0691: <4E>Lynn:'Don't tell anyone I'm here.I don't want to go to the Castle!'<44>Lynn:'I heard that a coup broke out at Keeleon and the King was overthrown.'<44>Lynn:'The new King,calling himself an alchemist,is performing horrible experiments.'
; Text $0692: Zzz...Zzz...
; Text $0693: No one's downstairs? My husband has gone somewhere again!
; Text $0694: <4E>Master:'So...you're finally leaving.I think it's a good idea to return to Kievs once in a while.'<44>Master:'Don't forget to visit your father's grave.Take care....'
; Text $0695: Bow,Wow,Wow!
; Text $0696: Neigh!'
; Text $0697: Brrr!'
; Text $0698: You've come to this cave looking for the Sphere of Silence,haven't you?'<4F>I've come from Monbaraba.I think you'd better give up.
; Text $0699: <4E><44>'I just can't find a way downstairs.'
; Text $069A: This is the Great Keeleon Castle.
; Text $069B: Though this Castle's Counsel is haughty,he's a coward.'<4F>Try making a big noise by his room.'<4F>He'll run screaming into the King's room.
; Text $069C: I believe only the Counsel knows where the King's room is.'<4F>Follow him and you may find it,but be careful.
; Text $069D: Where's my grandpa?
; Text $069E: There's a big coliseum in Endor across this sea....'<4F>I used to fight in the coliseum when I was young.I long for those days....
; Text $069F: Sorry,we're not open yet.
