; Huffman-compressed text group(s): $35
; Text $06A0: I'm Joy.Thanks for coming to see me.'<4F>But we open only at night.
; Text $06A1: Gwoon,Gwoon.
; Text $06A2: <4E><44>A letter is held in one hand.'<4F>Dear Father:<43>How are you? Are you coming back soon? Little Pipin misses you a lot.We're thinking of visiting you soon....
; Text $06A3: Foul gas began welling out of the mine and made many people sick.
; Text $06A4: This place,once a bustling town,is doomed.'<4F>My wife died here too....
; Text $06A5: You'd better flee at once or you'd end up like that person there.
; Text $06A6: Cough...Cough...Don't enter the mine if you cherish your life.'<4F>When the foul gas began welling out of the mine,monsters began appearing....Cough...Cough...
; Text $06A7: Watch out.Many monsters lurk here.
; Text $06A8: Many of my buddies died.Cough...Cough...
; Text $06A9: The poisonous gas or the monsters...I don't care.I'll continue until I find the gold.Dig and Dig and Dig and Dig...
; Text $06AA: This ship's destination is Endor.I'm excited!
; Text $06AB: I hear some people tried to destroy the King of Keeleon.
; Text $06AC: My fellow merchant,Taloon,has opened a shop in Endor.I'm on my way to congratulate him.
; Text $06AD: When will this ship sail? Be patient.'<4F>Why don't you talk with the passengers and the captain?
; Text $06AE: I'm Pipin.'<4F>We came to this country to see our father.But my sister says we're going back.I don't understand.
; Text $06AF: Oh,Joy! Why can't you...?'<4F>Darn! I could marry another girl! Weep...Weep...
; Text $06B0: This ship carries with it the memories of many different people.'<4F>I don't know what you've been through,but cheer up.'<4F>Good things will come if you live....
; Text $06B1: Doze...Doze...
; Text $06B2: Wait! You can't escape!
; Text $06B3: Hi,<49>,taking a walk? It's a beautiful day,isn't it?
; Text $06B4: I'm a traveling poet.I was lost in the mountains and found this village.'<4F>I didn't know there was a village deep in these mountains.
; Text $06B5: A poet wandered into this village last night.'<4F>Against village rules,I let him in.'<4F>I hope it won't cause trouble.
; Text $06B6: <49>,today I'll teach you how to cast a spell called Zap.'<4F>You look hungry.I'll teach you after lunch.
; Text $06B7: Ha! Bonk!'<57><4F>Ha,Ha,Ha! <49>,you must always guard yourself.Mastery of swordsmanship is harder than it appears.Understand?
; Text $06B8: <4E>Celia:'Good morning,<49>! It feels so good to rest like this!'<44>Celia:'<49>,I hope we can stay friends forever.'
; Text $06B9: Hi,<49>,this is a cellar.
; Text $06BA: Who are you? Are you a traveler? This is a woodsman's shack.'<4F>You look so gloomy.I hate gloomy kids.'<4F>Get off this mountain right away! You can go to the Castle.
; Text $06BB: Hey,wait! Look at your outfit! You can't travel like that.'<4F>Take those things in the jars over there!
; Text $06BC: This is Branca Castle.
; Text $06BD: Our King is upstairs.
; Text $06BE: Once a celestial maiden came down to the heart of the northern mountains.'<4F>She fell in love with a young woodsman,and they had a baby.'<4F>Where is the baby now? Oh,it's just a fairy tale.
; Text $06BF: Thanks to the cave Taloon made,now we can get to Endor in the far west.
